css:
@import url("https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&display=swap");
:root{--blue:#1D4ED8;--blue-d:#1E3A8A;--blue-l:#EAF1FF;--yel:#FACC15;--yel-l:#FEF9DB;--grn:#15803D;--grn-l:#E7F6EC;--red:#DC2626;--text:#1F2937;--muted:#6B7280;--line:#E5E9F0;--bg:#F6F8FC;--card:#fff;
--font:"Atkinson Hyperlegible",system-ui,-apple-system,"Segoe UI",sans-serif}
*,*::before,*::after{box-sizing:border-box}
body{margin:0;font-family:var(--font);font-size:16px;line-height:1.5;color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased}
a{color:inherit}img{display:block;max-width:100%}h1,h2,h3{margin:0;color:var(--blue-d)}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--yel);padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--yel);outline-offset:2px;border-radius:6px}
.app{display:grid;grid-template-columns:240px 1fr;min-height:100vh}
.side{background:var(--blue);color:#DCE6FF;padding:22px 14px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}
.brand{display:flex;align-items:center;gap:10px;color:#fff;font-weight:700;font-size:21px;text-decoration:none;padding:0 8px 22px}
.brand i{width:32px;height:32px;border-radius:10px;background:var(--yel)}
.side ul{list-style:none;padding:0;margin:0}
.side a{display:flex;gap:12px;align-items:center;padding:10px 12px;border-radius:10px;text-decoration:none;font-weight:700}
.side a:hover{background:rgba(255,255,255,.12);color:#fff}.side a.on{background:#fff;color:var(--blue)}
.term{margin-top:auto;background:rgba(255,255,255,.12);border-radius:14px;padding:14px;font-size:14px}.term b{display:block;color:#fff}
.term .t{height:8px;background:rgba(255,255,255,.2);border-radius:5px;margin-top:8px;overflow:hidden}.term .t i{display:block;height:100%;width:64%;background:var(--yel)}
.main{min-width:0;padding:24px 28px 40px}
.top{display:flex;align-items:center;gap:14px;margin-bottom:22px;flex-wrap:wrap}
.menu-btn{display:none;background:#fff;border:1px solid var(--line);border-radius:10px;padding:8px 10px;cursor:pointer}
.top h1{font-size:27px}.top p{margin:2px 0 0;color:var(--muted)}
.top .r{margin-left:auto;display:flex;gap:10px;align-items:center}
.search{display:flex;gap:8px;align-items:center;background:#fff;border:1px solid var(--line);border-radius:10px;padding:8px 12px;color:var(--muted);width:250px}
.search input{border:0;font:inherit;width:100%}.search input:focus{outline:none}
.btn{display:inline-flex;gap:6px;align-items:center;padding:10px 16px;border-radius:10px;font-weight:700;font-size:15px;border:1px solid var(--line);background:#fff;cursor:pointer;font-family:var(--font);color:var(--blue-d)}
.btn.pri{background:var(--blue);border-color:var(--blue);color:#fff}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:14px}
.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px}
.kpi small{color:var(--muted);font-weight:700}.kpi .v{font-size:30px;font-weight:700;color:var(--blue-d);margin:4px 0}
.kpi .d{font-size:14px;color:var(--grn);font-weight:700}
.kpi.y{background:var(--yel-l);border-color:#F4E3A1}
.row{display:grid;grid-template-columns:1.5fr 1fr;gap:14px;margin-bottom:14px}
.row3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px}
.card-h{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;gap:10px;flex-wrap:wrap}
.card h2{font-size:18px}
.days{display:flex;gap:4px}
.days button{border:1px solid var(--line);background:#fff;font:inherit;font-weight:700;font-size:14px;padding:5px 10px;border-radius:8px;cursor:pointer;color:var(--muted)}
.days button[aria-pressed="true"]{background:var(--blue);border-color:var(--blue);color:#fff}
#att{width:100%;height:240px}
.fees .big{font-size:34px;font-weight:700;color:var(--blue-d)}.fees .big small{font-size:16px;color:var(--muted)}
.fees .t{height:16px;background:var(--bg);border-radius:9px;overflow:hidden;margin:12px 0 6px;display:flex}
.fees .t i{display:block;height:100%}
.fees .lg{display:flex;justify-content:space-between;font-size:14px;color:var(--muted)}
.fees ul{list-style:none;padding:0;margin:16px 0 0}.fees li{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid var(--line);font-size:15px}
.fees li b.late{color:var(--red)}
.tt{list-style:none;padding:0;margin:0}
.tt li{display:grid;grid-template-columns:62px 1fr;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}
.tt time{font-weight:700;color:var(--blue)}.tt b{display:block}.tt small{color:var(--muted)}
.tt li.now{background:var(--yel-l);border-radius:10px;padding:10px;border:0}
.exam{display:flex;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line)}
.exam .d{width:52px;text-align:center;background:var(--blue-l);border-radius:12px;padding:6px 0;flex:none}
.exam .d b{display:block;font-size:20px;color:var(--blue-d);line-height:1.1}.exam .d small{font-size:12px;color:var(--blue);font-weight:700}
.exam small{color:var(--muted);display:block}
.notice{padding:12px;border-radius:12px;background:var(--bg);margin-bottom:10px;font-size:15px}
.notice b{display:block;color:var(--blue-d)}.notice small{color:var(--muted)}
.notice.imp{background:#FEECEC}.notice.imp b{color:var(--red)}
.stars{margin-top:16px}.stu{display:flex;align-items:center;gap:10px;padding:7px 0}
.stu img{width:36px;height:36px;border-radius:50%;object-fit:cover}.stu div{flex:1}.stu small{display:block;color:var(--muted)}
.stu strong{color:var(--grn)}
.foot{color:var(--muted);font-size:14px;margin-top:24px;text-align:center}.foot a{color:var(--blue)}
@media (max-width:1150px){.kpis{grid-template-columns:1fr 1fr}.row,.row3{grid-template-columns:1fr}}
@media (max-width:860px){.app{grid-template-columns:1fr}.side{position:fixed;left:0;top:0;width:250px;z-index:30;transform:translateX(-100%);transition:transform .25s}.side.open{transform:none}.menu-btn{display:block}.search{display:none}.main{padding:18px 14px}}
@media (max-width:520px){.kpis{grid-template-columns:1fr}}

javascript:
const Gr=["G1","G2","G3","G4","G5","G6","G7","G8","G9","G10","G11","G12"],A=[[93,95,92,96,94,91,90,93,92,95,94,96],[95,96,94,97,95,93,92,94,94,96,95,97],[92,94,91,95,93,90,89,92,91,94,93,95],[94,95,93,96,94,92,91,93,93,95,94,96],[90,92,89,93,91,88,86,89,88,91,90,92]];
function att(d){const s=document.getElementById('att'),W=s.clientWidth||700,H=240,pl=36,pb=24,mn=80,bw=(W-pl)/Gr.length;let g='';
[80,85,90,95,100].forEach(v=>{const y=H-pb-(v-mn)/20*(H-pb-10);g+=`<line x1="${pl}" x2="${W}" y1="${y}" y2="${y}" stroke="#E5E9F0"/><text x="${pl-6}" y="${y+4}" text-anchor="end" font-size="11" fill="#6B7280">${v}%</text>`});
A[d].forEach((v,i)=>{const h=(v-mn)/20*(H-pb-10),x=pl+i*bw+bw*.18,low=v<91;g+=`<rect x="${x}" y="${H-pb-h}" width="${bw*.64}" height="${h}" rx="5" fill="${low?'#FACC15':'#1D4ED8'}"><title>${Gr[i]}: ${v}%</title></rect><text x="${x+bw*.32}" y="${H-7}" text-anchor="middle" font-size="11" fill="#6B7280">${Gr[i]}</text>`});
s.setAttribute('viewBox',`0 0 ${W} ${H}`);s.innerHTML=g}
document.querySelectorAll('#days button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#days button').forEach(x=>x.setAttribute('aria-pressed',x===b));att(+b.dataset.d)}));
att(1);window.addEventListener('resize',()=>att(+document.querySelector('#days [aria-pressed=true]').dataset.d));
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
